import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"Payments & ledgers","description":"","frontmatter":{},"headers":[],"relativePath":"guide/accounts.md","filePath":"guide/accounts.md","lastUpdated":1791960929000}'),o={name:"guide/accounts.md"};function i(s,e,c,l,d,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="payments-ledgers" tabindex="-1">Payments &amp; ledgers <a class="header-anchor" href="#payments-ledgers" aria-label="Permalink to &quot;Payments &amp; ledgers&quot;">​</a></h1><h2 id="payment-receipt" tabindex="-1">Payment Receipt <a class="header-anchor" href="#payment-receipt" aria-label="Permalink to &quot;Payment Receipt&quot;">​</a></h2><p><strong>Payment Receipt</strong> (Shift+F3) records money received from a customer or paid to a supplier.</p><ol><li>Choose <strong>Receive</strong> or <strong>Pay</strong>.</li><li>Select the party.</li><li>Enter the amount and mode (cash, bank, UPI, cheque).</li><li>Optionally allocate against outstanding bills.</li><li>Save.</li></ol><h2 id="customer-ledger" tabindex="-1">Customer Ledger <a class="header-anchor" href="#customer-ledger" aria-label="Permalink to &quot;Customer Ledger&quot;">​</a></h2><p><strong>Customer Ledger</strong> (Shift+F6) shows every transaction of a customer with a running balance. Click any line to see the voucher behind it. Balances refresh live when a new bill or payment is posted.</p><h2 id="general-ledger" tabindex="-1">General Ledger <a class="header-anchor" href="#general-ledger" aria-label="Permalink to &quot;General Ledger&quot;">​</a></h2><p>Browse any account — cash, bank, expenses, income — with running balance and date filters.</p><h2 id="journal-contra" tabindex="-1">Journal / Contra <a class="header-anchor" href="#journal-contra" aria-label="Permalink to &quot;Journal / Contra&quot;">​</a></h2><p><strong>Journal Contra</strong> (Shift+F8) records manual adjustments and transfers between cash and bank accounts.</p><h2 id="cash-box-entry" tabindex="-1">Cash Box Entry <a class="header-anchor" href="#cash-box-entry" aria-label="Permalink to &quot;Cash Box Entry&quot;">​</a></h2><p>Record day-to-day shop expenses paid in cash.</p><h2 id="cheque-register" tabindex="-1">Cheque Register <a class="header-anchor" href="#cheque-register" aria-label="Permalink to &quot;Cheque Register&quot;">​</a></h2><p>Track cheques received and issued, with their clearing status.</p><h2 id="unreconciled-entries-payment-reconciliation" tabindex="-1">Unreconciled Entries &amp; Payment Reconciliation <a class="header-anchor" href="#unreconciled-entries-payment-reconciliation" aria-label="Permalink to &quot;Unreconciled Entries &amp; Payment Reconciliation&quot;">​</a></h2><p>List payments not yet matched to invoices and link them, so that outstanding balances are accurate.</p><h2 id="chart-of-accounts" tabindex="-1">Chart of Accounts <a class="header-anchor" href="#chart-of-accounts" aria-label="Permalink to &quot;Chart of Accounts&quot;">​</a></h2><p>View the account tree and create new accounts where permitted.</p>',18)])])}const m=a(o,[["render",i]]);export{p as __pageData,m as default};
